// ------------------------------------------------------------------
// iNaturalist range / observation map viewer, split by child taxon.
//
// For a chosen taxon (genus, species, family, ...) we pull its direct
// children from the iNat API and overlay each child in a distinct
// color so their ranges are visually separable.
//
// Two data sources, because iNat serves them differently:
//   * "Range polygons" - the expert/imported range tiles from
//     tiles.inaturalist.org/v1/taxon_ranges/{id}. These only exist for
//     taxa that have a range on file (mostly species; subspecies
//     usually have none, so they render blank).
//   * "Observations" - the community observation grid from
//     api.inaturalist.org/v1/grid, filtered by taxon_id. These go all
//     the way down to subspecies, which is why the Puma concolor
//     north/south split only shows up in this mode.
// Both endpoints accept a ?color= param and send CORS headers.
// ------------------------------------------------------------------

// The Leaflet global comes from a CDN <script> in the page; type it without
// bundling so `L` stays a runtime global but is fully checked.
declare const L: typeof import('leaflet');

const RANGE_TILE_URL = 'https://tiles.inaturalist.org/v1/taxon_ranges/{id}/{z}/{x}/{y}.png?color={color}';
const GRID_TILE_URL  = 'https://api.inaturalist.org/v1/grid/{z}/{x}/{y}.png?taxon_id={id}&color={color}';
// Observations of the parent taxon with the colored children excluded —
// the "everyone else" layer so capped-out taxa are still visible.
const REMAINDER_TILE_URL = 'https://api.inaturalist.org/v1/grid/{z}/{x}/{y}.png?taxon_id={id}&without_taxon_id={exclude}&color={color}';
const REMAINDER_COLOR = '#9aa0a6';   // pale grey: present but visually recessive under the colored taxa
const API = 'https://api.inaturalist.org/v1';

// Per-child colors are generated in the OKLCH (Oklab) color space
// rather than hand-picked. Holding lightness and chroma fixed while
// spreading hue evenly around the wheel gives a set of colors that are
// perceptually uniform — equally bright and equally saturated — so no
// one taxon visually dominates and every pair is equally separable,
// for any number of children.
const PALETTE_LIGHTNESS = 0.70;   // Oklab L: mid-bright, reads over light and satellite bases
const PALETTE_CHROMA = 0.15;      // Oklab C: vivid without pushing too many hues out of sRGB gamut
const PALETTE_START_HUE = 25;     // start at warm orange-red so the most-observed child is a familiar color

// A large genus can have hundreds of children; drawing a tile layer for
// each overwhelms both the map and the eye. We keep only the most-
// observed children, capped here. Twelve is about the limit at which
// evenly-spaced hues stay tellable apart.
const MAX_CHILDREN = 12;

// Convert an Oklab lightness/chroma/hue triple to an sRGB hex string,
// following Björn Ottosson's Oklab reference conversion. Channels are
// clamped into gamut, which slightly desaturates the few hues that
// exceed sRGB at this chroma.
function oklchToHex(lightness: number, chroma: number, hueDegrees: number): string {
    const hueRadians = hueDegrees * Math.PI / 180;
    const a = chroma * Math.cos(hueRadians);
    const b = chroma * Math.sin(hueRadians);

    const l_ = lightness + 0.3963377774 * a + 0.2158037573 * b;
    const m_ = lightness - 0.1055613458 * a - 0.0638541728 * b;
    const s_ = lightness - 0.0894841775 * a - 1.2914855480 * b;
    const l = l_ * l_ * l_;
    const m = m_ * m_ * m_;
    const s = s_ * s_ * s_;

    const lr = 4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s;
    const lg = -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s;
    const lb = -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s;

    return '#' + [lr, lg, lb].map(linearToHexChannel).join('');
}

// Gamma-encode one linear-light channel and format it as a two-digit
// hex byte, clamping out-of-gamut values to [0, 1].
function linearToHexChannel(value: number): string {
    const encoded = value <= 0.0031308
        ? 12.92 * value
        : 1.055 * Math.pow(value, 1 / 2.4) - 0.055;
    const byte = Math.round(Math.min(1, Math.max(0, encoded)) * 255);
    return byte.toString(16).padStart(2, '0');
}

// Build `count` evenly-spaced OKLCH colors for the child taxa.
function generatePalette(count: number): string[] {
    if (count <= 0) return [];
    const step = 360 / count;
    const palette: string[] = [];
    for (let i = 0; i < count; i++) {
        palette.push(oklchToHex(PALETTE_LIGHTNESS, PALETTE_CHROMA, PALETTE_START_HUE + i * step));
    }
    return palette;
}

const map = L.map('map', { worldCopyJump: true }).setView([15, -30], 3);

// Base layers. Both the OpenStreetMap volunteer server (403 "Access
// blocked") and CARTO's free tiles (now key-gated) refuse generic
// apps, so we use Esri's key-free ArcGIS Online services. The default
// is a muted light-gray base plus a transparent labels layer, because
// a subdued map makes the colored range overlays pop.
const esriAttribution = 'Tiles &copy; Esri';
const grayBase = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Light_Gray_Base/MapServer/tile/{z}/{y}/{x}', {
    maxZoom: 16, attribution: esriAttribution
});
const grayLabels = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Light_Gray_Reference/MapServer/tile/{z}/{y}/{x}', {
    maxZoom: 16, attribution: ''
});
const light = L.layerGroup([grayBase, grayLabels]);
const streets = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}', {
    maxZoom: 19, attribution: esriAttribution
});
const satellite = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
    maxZoom: 18, attribution: esriAttribution
});
light.addTo(map);
L.control.layers({ 'Light': light, 'Street map': streets, 'Satellite': satellite }, null as any, { position: 'topleft' }).addTo(map);

// iNat overlays ride in their own pane above the basemap. The grey
// remainder sits in a lower pane so the colored taxa always draw on top.
map.createPane('inatRemainderPane');
map.getPane('inatRemainderPane')!.style.zIndex = '390';
map.getPane('inatRemainderPane')!.style.pointerEvents = 'none';
map.createPane('inatPane');
map.getPane('inatPane')!.style.zIndex = '400';
map.getPane('inatPane')!.style.pointerEvents = 'none';

let currentMode = 'observations';
let overlayOpacity = 0.65;
let wildOnly = false;        // captive=false — exclude captive/cultivated observations
let researchOnly = false;    // quality_grade=research — research-grade observations only

// When a legend row is hovered, its taxon jumps to near-opaque and the
// rest fade to faint context, so it's obvious which layer is which.
const HIGHLIGHT_OPACITY = 0.95;
const DIMMED_OPACITY = 0.1;

// Entries the legend renders and toggles. Each: { id, name, rank,
// common, color, enabled, layer(null until added) }.
let entries: any[] = [];

// The taxon currently in focus and which page of its children we show.
// Paging through the "Other" group advances childOffset by MAX_CHILDREN
// without refetching the taxon.
let currentTaxon: any = null;
let childOffset = 0;

function setStatus(msg: string) { document.getElementById('status')!.innerText = msg || ''; }

// Accept a bare id, a name, or any iNat taxa URL / #anchor and reduce
// it to something we can resolve. Returns { id } or { query }.
function parseTaxonInput(raw: string): any {
    const text = raw.trim();
    if (!text) return null;
    const urlMatch = text.match(/taxa\/(\d+)/);
    if (urlMatch) return { id: parseInt(urlMatch[1], 10) };
    if (/^\d+$/.test(text)) return { id: parseInt(text, 10) };
    return { query: text };
}

async function resolveTaxonId(parsed: any): Promise<any> {
    if (parsed.id) return parsed.id;
    const res = await fetch(`${API}/taxa/autocomplete?q=${encodeURIComponent(parsed.query)}&per_page=1`);
    const data = await res.json();
    if (!data.results || data.results.length === 0) return null;
    return data.results[0].id;
}

// ------------------------------------------------------------------
// Live taxon autocomplete — the same /taxa/autocomplete endpoint the
// main iNaturalist site uses, rendered as a typeahead dropdown with a
// thumbnail, scientific and common name, rank, and observation count.
// ------------------------------------------------------------------

const AUTOCOMPLETE_DEBOUNCE_MS = 220;   // wait out a burst of typing before querying, so it's one request per pause, not per key
const AUTOCOMPLETE_LIMIT = 8;

let suggestionItems: any[] = [];
let activeSuggestion = -1;
let suggestionTimer: ReturnType<typeof setTimeout> | null = null;

// Query the API a short beat after the user stops typing. Bare ids and
// pasted URLs aren't name searches, so they get no dropdown.
function onSearchInput() {
    const text = (document.getElementById('taxonInput') as HTMLInputElement).value.trim();
    if (suggestionTimer) clearTimeout(suggestionTimer);
    if (!text || /^\d+$/.test(text) || /taxa\/\d+/.test(text)) { hideSuggestions(); return; }
    suggestionTimer = setTimeout(() => fetchSuggestions(text), AUTOCOMPLETE_DEBOUNCE_MS);
}

async function fetchSuggestions(query: string) {
    try {
        const res = await fetch(`${API}/taxa/autocomplete?q=${encodeURIComponent(query)}&per_page=${AUTOCOMPLETE_LIMIT}`);
        const data = await res.json();
        // Drop a response that arrived after the user kept typing.
        if ((document.getElementById('taxonInput') as HTMLInputElement).value.trim() !== query) return;
        renderSuggestions(data.results || []);
    } catch (err) {
        console.warn('autocomplete request failed', err);
    }
}

// The inner markup for one suggestion row.
function suggestionRowMarkup(item: any): string {
    const photo = item.default_photo && item.default_photo.square_url;
    const img = photo ? `<img src="${photo}" alt="">` : '<img alt="">';
    const common = item.preferred_common_name ? ` — ${item.preferred_common_name}` : '';
    const count = item.observations_count != null ? ` · ${item.observations_count.toLocaleString()} obs` : '';
    return `${img}<span class="s-text">`
        + `<span class="s-name"><em>${item.name}</em>${common}</span>`
        + `<span class="s-meta">${item.rank}${count}</span></span>`;
}

function renderSuggestions(items: any[]) {
    suggestionItems = items;
    activeSuggestion = -1;
    const ul = document.getElementById('suggestions')!;
    if (!items.length) { hideSuggestions(); return; }
    ul.innerHTML = '';
    items.forEach((item, index) => {
        const li = document.createElement('li');
        li.innerHTML = suggestionRowMarkup(item);
        li.addEventListener('click', () => selectSuggestion(index));
        ul.appendChild(li);
    });
    ul.hidden = false;
}

function hideSuggestions() {
    suggestionItems = [];
    activeSuggestion = -1;
    const ul = document.getElementById('suggestions')!;
    ul.hidden = true;
    ul.innerHTML = '';
}

function selectSuggestion(index: number) {
    const item = suggestionItems[index];
    if (!item) return;
    (document.getElementById('taxonInput') as HTMLInputElement).value = item.name;
    hideSuggestions();
    loadTaxonById(item.id);
}

// Move the highlight through the dropdown, wrapping at both ends.
function moveActiveSuggestion(delta: number) {
    const ul = document.getElementById('suggestions')!;
    const count = suggestionItems.length;
    if (!count) return;
    activeSuggestion = (activeSuggestion + delta + count) % count;
    Array.from(ul.children).forEach((li, i) => li.classList.toggle('active', i === activeSuggestion));
    ul.children[activeSuggestion].scrollIntoView({ block: 'nearest' });
}

// Arrow keys navigate the dropdown; Enter picks the highlight or, with
// none highlighted, resolves whatever is typed; Escape closes it.
function onSearchKeydown(event: KeyboardEvent) {
    const open = !(document.getElementById('suggestions') as HTMLElement).hidden && suggestionItems.length > 0;
    if (open && event.key === 'ArrowDown') { event.preventDefault(); moveActiveSuggestion(1); }
    else if (open && event.key === 'ArrowUp') { event.preventDefault(); moveActiveSuggestion(-1); }
    else if (event.key === 'Enter') {
        event.preventDefault();
        if (open && activeSuggestion >= 0) selectSuggestion(activeSuggestion);
        else loadFromInput();
    } else if (event.key === 'Escape') {
        hideSuggestions();
    }
}

// Close the dropdown when clicking anywhere outside the search box.
function onDocumentMousedown(event: MouseEvent) {
    const input = document.getElementById('taxonInput');
    const ul = document.getElementById('suggestions')!;
    if (event.target === input || ul.contains(event.target as Node)) return;
    hideSuggestions();
}

document.addEventListener('mousedown', onDocumentMousedown);

async function fetchTaxon(id: number): Promise<any> {
    const res = await fetch(`${API}/taxa/${id}`);
    const data = await res.json();
    return data.results && data.results[0];
}

// A span this wide almost always means captive/errant outlier
// observations rather than a genuinely global range, so we skip the
// fit and leave the world view rather than zoom out to nothing useful.
const MAX_FIT_LAT_SPAN = 130;
const MAX_FIT_LNG_SPAN = 220;

// Fit the map to where the parent taxon has observations, so you land
// on the animal instead of the middle of the ocean. Bounds skewed by
// outliers (see the constants above) are ignored.
async function fitToTaxon(id: number) {
    try {
        const res = await fetch(`${API}/observations?taxon_id=${id}&per_page=0&return_bounds=true`);
        const data = await res.json();
        const b = data.total_bounds;
        if (!b || b.swlat == null) return;
        const latSpan = b.nelat - b.swlat;
        const lngSpan = b.nelng - b.swlng;
        if (latSpan > MAX_FIT_LAT_SPAN || lngSpan > MAX_FIT_LNG_SPAN) return;
        map.fitBounds([[b.swlat, b.swlng], [b.nelat, b.nelng]], { padding: [20, 20] });
    } catch (err) {
        // Non-fatal: leave the map where it is if bounds lookup fails.
        console.warn('bounds lookup failed', err);
    }
}

// Extra query params for observation tiles from the active filters.
// Range polygons ignore these — they aren't observation queries.
function observationFilterParams(): string {
    const params: string[] = [];
    if (researchOnly) params.push('quality_grade=research');
    if (wildOnly) params.push('captive=false');
    return params.length ? '&' + params.join('&') : '';
}

// The tile URL for an entry, or null when it can't render in the
// current mode (the grey remainder is observation-only — range polygons
// have no "everything except these taxa" equivalent).
function tileUrlFor(entry: any): string | null {
    if (entry.isRemainder) {
        if (currentMode !== 'observations') return null;
        return REMAINDER_TILE_URL
            .replace('{id}', entry.id)
            .replace('{exclude}', entry.exclude)
            .replace('{color}', encodeURIComponent(entry.color))
            + observationFilterParams();
    }
    if (currentMode === 'range') {
        return RANGE_TILE_URL.replace('{id}', entry.id).replace('{color}', encodeURIComponent(entry.color));
    }
    return GRID_TILE_URL
        .replace('{id}', entry.id)
        .replace('{color}', encodeURIComponent(entry.color))
        + observationFilterParams();
}

function makeLayer(entry: any): ReturnType<typeof L.tileLayer> | null {
    const url = tileUrlFor(entry);
    if (!url) return null;
    return L.tileLayer(url, {
        pane: entry.isRemainder ? 'inatRemainderPane' : 'inatPane',
        opacity: overlayOpacity,
        maxZoom: 18,
        attribution: '&copy; <a href="https://www.inaturalist.org">iNaturalist</a>'
    });
}

function addEntryLayer(entry: any) {
    if (entry.layer) return;
    const layer = makeLayer(entry);
    if (!layer) return;
    entry.layer = layer;
    layer.addTo(map);
}

function removeEntryLayer(entry: any) {
    if (!entry.layer) return;
    map.removeLayer(entry.layer);
    entry.layer = null;
}

// Rebuild every currently-enabled layer (used when mode/opacity change).
function refreshLayers() {
    for (const entry of entries) {
        removeEntryLayer(entry);
        if (entry.enabled) addEntryLayer(entry);
    }
}

function toggleEntry(index: number, checked: boolean) {
    const entry = entries[index];
    entry.enabled = checked;
    if (checked) addEntryLayer(entry); else removeEntryLayer(entry);
}

function setMode(mode: string) {
    currentMode = mode;
    document.getElementById('modeNote')!.innerText = mode === 'range'
        ? 'Range polygons exist mainly at species level. Children without a range on file (often subspecies) show nothing here — switch to Observations to see them.'
        : 'Observation grid, colored per child taxon. Denser cells = more observations. This mode reaches subspecies.';
    renderLegend();
    refreshLayers();
}

function setWildOnly(checked: boolean) {
    wildOnly = checked;
    refreshLayers();
}

function setResearchOnly(checked: boolean) {
    researchOnly = checked;
    refreshLayers();
}

function setOpacity(val: any) {
    overlayOpacity = val / 100;
    document.getElementById('opacityVal')!.innerText = val;
    for (const entry of entries) {
        if (entry.layer) entry.layer.setOpacity(overlayOpacity);
    }
}

// Emphasize one taxon: bring it to the front at high opacity and fade
// the others. Called while a legend row is hovered.
function highlightEntry(index: number) {
    entries.forEach((entry, i) => {
        if (entry.layer) entry.layer.setOpacity(i === index ? HIGHLIGHT_OPACITY : DIMMED_OPACITY);
    });
    const target = entries[index];
    if (target && target.layer && target.layer.bringToFront) target.layer.bringToFront();
}

// Restore every layer to the current slider opacity (hover ended).
function clearHighlight() {
    for (const entry of entries) {
        if (entry.layer) entry.layer.setOpacity(overlayOpacity);
    }
}

// A single drill-up link to the direct parent taxon (the last entry in
// the root-to-parent ancestors list).
function renderBreadcrumb(taxon: any) {
    const el = document.getElementById('breadcrumb')!;
    const ancestors = taxon.ancestors || [];
    if (!ancestors.length) { el.innerHTML = ''; return; }
    const parent = ancestors[ancestors.length - 1];
    el.innerHTML = `↑ <a data-id="${parent.id}">${parent.name}</a> <span class="sep">(${parent.rank})</span>`;
    const link = el.querySelector('a')!;
    link.addEventListener('click', () => loadTaxonById(parseInt(link.dataset.id!, 10)));
}

// A taxon thumbnail for a legend row, or a same-sized blank box when
// the taxon has no photo (or for the grey remainder, which has none).
function legendThumbMarkup(entry: any): string {
    return entry.photo
        ? `<img class="legend-thumb" src="${entry.photo}" alt="">`
        : '<span class="legend-thumb"></span>';
}

// The inner markup of a legend row's name, which differs for the grey
// remainder (a plain label) versus a real taxon (italic name + rank).
function legendNameMarkup(entry: any): string {
    if (entry.isRemainder) {
        return `<span class="legend-name"><span class="sci">${entry.name} <span style="color:#9a9a9a">(click to page through)</span></span></span>`;
    }
    const common = entry.common ? `<span class="common">${entry.common}</span>` : '';
    const rankLabel = entry.isParent ? 'whole taxon' : entry.rank;
    return `<span class="legend-name">`
        + `<span class="sci"><em>${entry.name}</em> <span style="color:#9a9a9a">(${rankLabel})</span></span>`
        + `${common}</span>`;
}

function renderLegend() {
    const legend = document.getElementById('legend')!;
    legend.innerHTML = '';
    entries.forEach((entry, index) => {
        // The remainder is observation-only, so it has no row in range mode.
        if (entry.isRemainder && currentMode !== 'observations') return;
        const row = document.createElement('div');
        row.className = 'legend-item' + (entry.isParent ? ' parent' : '');
        // A real child taxon drills into itself; the grey remainder pages
        // to the next set of taxa; the parent (current focus) does neither.
        const drillable = !entry.isParent && !entry.isRemainder;
        const pageable = entry.isRemainder;
        const title = drillable ? `View ${entry.name}` : (pageable ? 'Show the next taxa' : '');
        const content = (drillable || pageable)
            ? `<button type="button" class="drill" title="${title}">${legendThumbMarkup(entry)}${legendNameMarkup(entry)}</button>`
            : `<span class="nondrill">${legendThumbMarkup(entry)}${legendNameMarkup(entry)}</span>`;
        row.innerHTML =
            `<input type="checkbox" ${entry.enabled ? 'checked' : ''} data-index="${index}" title="Toggle layer">
             <span class="swatch" style="background:${entry.color}"></span>
             ${content}`;
        row.querySelector('input')!.addEventListener('change', (e) => toggleEntry(index, (e.target as HTMLInputElement).checked));
        const drill = row.querySelector('.drill');
        if (drill) drill.addEventListener('click', () => (drillable ? loadTaxonById(entry.id) : pageChildrenForward()));
        row.addEventListener('mouseenter', () => highlightEntry(index));
        row.addEventListener('mouseleave', clearHighlight);
        legend.appendChild(row);
    });

    if (childOffset > 0) {
        const resetRow = document.createElement('div');
        resetRow.className = 'legend-item';
        resetRow.innerHTML = '<button type="button" class="drill pager-reset">↩ Back to most-observed</button>';
        resetRow.querySelector('button')!.addEventListener('click', resetChildren);
        legend.appendChild(resetRow);
    }
}

// Active child taxa, most-observed first. Sorting by observation count
// means the most common taxon is always rank 0, so it always receives
// the same anchor color regardless of how the genus is composed.
function activeChildrenByObservations(taxon: any): any[] {
    const children = (taxon.children || []).filter((child: any) => child.is_active !== false);
    children.sort((a: any, b: any) => (b.observations_count || 0) - (a.observations_count || 0));
    return children;
}

// Build the legend entries: the parent taxon first (dashed, off by
// default so children read cleanly), then the top child taxa colored.
// Returns the entries plus how many active children exist versus how
// many we actually show, so the caller can report truncation.
function buildEntries(taxon: any): { entries: any[]; totalActive: number; shownCount: number } {
    const parentEntry = {
        id: taxon.id,
        name: taxon.name,
        rank: taxon.rank,
        common: taxon.preferred_common_name || '',
        photo: taxon.default_photo ? taxon.default_photo.square_url : null,
        color: '#555555',
        enabled: false,
        isParent: true,
        layer: null
    };
    const sorted = activeChildrenByObservations(taxon);
    const shown = sorted.slice(childOffset, childOffset + MAX_CHILDREN);
    const palette = generatePalette(shown.length);
    const childEntries = shown.map((child: any, i: number) => ({
        id: child.id,
        name: child.name,
        rank: child.rank,
        common: child.preferred_common_name || '',
        photo: child.default_photo ? child.default_photo.square_url : null,
        color: palette[i],
        enabled: true,
        isParent: false,
        layer: null
    }));

    const entries: any[] = [parentEntry, ...childEntries];
    const remainderCount = sorted.length - shown.length;
    if (remainderCount > 0) {
        entries.push({
            id: taxon.id,
            exclude: shown.map((child: any) => child.id).join(','),
            name: `Other ${remainderCount} taxa`,
            rank: 'remainder',
            common: '',
            color: REMAINDER_COLOR,
            enabled: true,
            isParent: false,
            isRemainder: true,
            layer: null
        });
    }
    return { entries, totalActive: sorted.length, shownCount: shown.length };
}

// Rebuild the legend and overlays for the current taxon at the current
// child page. Used by both a fresh load and by paging the "Other" group.
function applyChildWindow() {
    for (const entry of entries) removeEntryLayer(entry);
    const built = buildEntries(currentTaxon);
    entries = built.entries;
    if (built.totalActive === 0) {
        setStatus('This taxon has no child taxa — showing the taxon itself. Enable it in the legend.');
        entries[0].enabled = true;
    } else if (built.totalActive > built.shownCount || childOffset > 0) {
        const start = childOffset + 1;
        const end = childOffset + built.shownCount;
        setStatus(`Showing ${start}–${end} of ${built.totalActive} child taxa by observations.`);
    } else {
        setStatus(`${built.shownCount} child ${built.shownCount === 1 ? 'taxon' : 'taxa'} loaded.`);
    }
    renderLegend();
    refreshLayers();
}

// Advance to the next page of children, wrapping back to the top.
function pageChildrenForward() {
    if (!currentTaxon) return;
    const total = activeChildrenByObservations(currentTaxon).length;
    const next = childOffset + MAX_CHILDREN;
    childOffset = next >= total ? 0 : next;
    applyChildWindow();
}

// Jump back to the first, most-observed page of children.
function resetChildren() {
    childOffset = 0;
    applyChildWindow();
}

// Load a taxon we already have the id for (from a suggestion click or
// a resolved search) and rebuild the whole overlay.
async function loadTaxonById(id: number) {
    setStatus('Loading…');
    for (const entry of entries) removeEntryLayer(entry);
    entries = [];

    try {
        const taxon = await fetchTaxon(id);
        if (!taxon) { setStatus('Could not load taxon ' + id + '.'); return; }

        currentTaxon = taxon;
        childOffset = 0;
        (document.getElementById('taxonInput') as HTMLInputElement).value = taxon.name;
        renderBreadcrumb(taxon);
        const common = taxon.preferred_common_name ? ` — ${taxon.preferred_common_name}` : '';
        const titlePhoto = taxon.default_photo ? taxon.default_photo.square_url : null;
        const titleThumb = titlePhoto
            ? `<img class="legend-thumb" src="${titlePhoto}" alt="">`
            : '<span class="legend-thumb"></span>';
        document.getElementById('taxonTitle')!.innerHTML =
            `${titleThumb}<span><strong><em>${taxon.name}</em></strong> (${taxon.rank})${common}</span>`;

        applyChildWindow();
        await fitToTaxon(id);
    } catch (err) {
        console.error(err);
        setStatus('Error loading taxon: ' + (err as Error).message);
    }
}

// Resolve whatever is typed in the box (name, id, or URL) and load it.
async function loadFromInput() {
    const parsed = parseTaxonInput((document.getElementById('taxonInput') as HTMLInputElement).value);
    if (!parsed) { setStatus('Enter a taxon name, ID, or URL.'); return; }
    hideSuggestions();
    try {
        const id = await resolveTaxonId(parsed);
        if (!id) { setStatus('No taxon found for that search.'); return; }
        await loadTaxonById(id);
    } catch (err) {
        console.error(err);
        setStatus('Error resolving taxon: ' + (err as Error).message);
    }
}

// The HTML calls these from inline handlers; module scope isn't global, so
// re-expose them on window to keep those handlers working.
(window as any).onSearchInput = onSearchInput;
(window as any).onSearchKeydown = onSearchKeydown;
(window as any).loadFromInput = loadFromInput;
(window as any).setMode = setMode;
(window as any).setWildOnly = setWildOnly;
(window as any).setResearchOnly = setResearchOnly;
(window as any).setOpacity = setOpacity;

// Seed the mode note and load the default example on first paint.
setMode(currentMode);
loadFromInput();

export {};
